#pragma once
#include <cstdint>

// Addresses in sacred.exe. They are found at startup from byte signatures (sacred_sigs.inc, generated by
// tools/gen_sigs.py from the German build and checked against the English one); the comments give the German
// addresses, the names match the Ghidra program "/sacred.exe (DE)". Lines that are only comments are not resolved.
namespace Sacred::Addr
{
    // dxDriver7 (DirectDraw7 + Direct3D7 wrapper, one global instance)
    // g_pDxDriver: DE 00CDA99C
    // dxDriver7_ctor: DE 00644960
    // dxDriver7_createSurface: DE 00644BE0
    // dxDriver7_createZBuffer: DE 00645000
    inline uintptr_t dxDriver7_init{};                  // DE 00645390
    inline uintptr_t dxDriver7_flip{};                  // DE 00645F70
    inline uintptr_t dxDriver7_lockBack{};              // DE 00646280
    // dxDriver7_unlockBack: DE 006462F0
    // dxDriver7_setFullViewport: DE 00646510
    // dxDriver7_drawTexturedQuad: DE 006466B0
    inline uintptr_t dxDriver7_drawLoadingScreen{};     // DE 006469D0
    // dxDriver7_beginScene: DE 00646F50
    // dxDriver7_endScene: DE 00646FD0

    // cDxDevices::findMode(w, h, bpp, flags) -> mode record; called once by initApp with 1024x768.
    inline uintptr_t cDxDevices_findMode{};             // DE 00644260

    // Return address of the CreateWindowExA call that creates the main game window.
    inline uintptr_t mainWindowCreateReturn{};          // DE 00664A5E

    // Mouse: getClientCursorPos(hwnd, POINT*) is the only cursor read; cMouse is the singleton the UI and world poll.
    inline uintptr_t getClientCursorPos{};              // DE 0066E500
    inline uintptr_t cMouse_instance{};                 // DE 006550F0
    inline uintptr_t cMouse_renderCursor{};             // DE 006555E0; (device, flag)

    // Renders the hero into the back buffer and reads the centered region back for the savegame JPEG.
    inline uintptr_t renderSavePortrait{};              // DE 004B1740; thiscall (path, w, h, scale), this = 0xAAAF00
    // Plays an intro/cutscene video through DirectShow onto a fullscreen 1024x768 TL quad.
    inline uintptr_t playVideo{};                       // DE 006A0C60; thiscall, 5 stack args

    // UI framework (cUI_Control2 / cUI_Window2 / cUI_Manager)
    inline uintptr_t g_pUiManager{};                    // DE 017ECB3C; cUI_Manager*
    inline uintptr_t cUI_Manager_isCursorOverUi{};      // DE 0075A370; thiscall (x, y) -> bool, UI coordinates
    // cUI_Control2_ctor: DE 00731420; (name, x, y, w|h<<16, parent, flags)
    // cUI_Window2_addChild: DE 00727120; pushes into the children vector
    // cUI_Manager_createGameWindows: DE 007593D0
    // cUI_Window2_typeDescriptor: DE 009DE188

    // Texture manager (one instance): loads textures on use, evicts least recently used ones above a budget.
    // initApp computes the budget from GlobalMemoryStatus and the reported video memory (min 32 MB).
    inline uintptr_t g_pTextureManager{};               // DE 013E57B8
    inline uintptr_t cTextureManager_init{};            // DE 0065EA20; thiscall (budgetBytes)

    // cEngine
    // initApp: DE 00815620
    inline uintptr_t cEngine_renderThreadRun{};         // DE 0060E3F0; fastcall (engine), loops until shutdown
    // Frame limiter: cdecl (double, uint16 fps); spins with Sleep(0) until 1/fps passed since its last return.
    // The render loop calls it with 60 before each flip (skipped if 0x182CDBC has 0x4000), the menu loop too.
    inline uintptr_t frameLimiter{};                    // DE 0060AA90
    inline uintptr_t renderLimiterReturn{};             // DE 0060EB0E
    // cEngine_updateWorldCursor (0x611F10) asks the UI whether the cursor is over a window before picking.
    inline uintptr_t worldCursorUiTestCall{};           // DE 00611F83
    // cEngine_captureInternal: DE 00613710
    inline uintptr_t captureLockBackReturn{};           // DE 0061374B; after captureInternal's call to lockBack

    // 3D model path: cCreature vtable[5] render -> cObject3D_render (needs the Granny model attached, flags bit 26)
    // -> cObject3D_drawModel -> cGranny_render* -> DrawIndexedPrimitiveStrided.
    inline uintptr_t cCreature_render{};                // DE 00599880; thiscall (device, 0)
    inline uintptr_t cObject3D_render{};                // DE 0044B400; thiscall (device, ?)
    inline uintptr_t cObject3D_drawModel{};             // DE 0044ABA0; thiscall (device, model, instance, flags64)

    // World <-> pixel conversion (cdecl (out, point, rotation, projection) -> out). Pixels assume a projection
    // spanning 1024x768 pixels: true for g_unzoomedProjection, not for the device projection (W x H).
    inline uintptr_t pixelsToWorld{};                   // DE 00623A20
    inline uintptr_t worldToPixels{};                   // DE 00623C40
    inline uintptr_t g_unzoomedProjection{};            // DE 0182CCF0

    // Ground: renderTileRow draws each tile's base through the quad batcher (cWorldView + 0x86890) and collects
    // tiles with blend layers into a fixed array (at most 0x6D5 per frame); after all rows cWorldView0_render
    // flushes the batcher and cWorldView_drawTileLayers draws the collected layers.
    inline uintptr_t cWorldView_renderTileRow{};        // DE 0062B000; thiscall (device, rowPos, detail)
    inline uintptr_t cWorldView_drawTileLayers{};       // DE 0062D530; thiscall (device)
    inline uintptr_t cQuadBatcher_flush{};              // DE 00629420; thiscall (device)
    // Draws the collected water/lava tiles (glow pass, then the tiles) and sets the water ambience from their
    // count and average position.
    inline uintptr_t cWorldView_drawWaterTiles{};       // DE 0062DE70; thiscall (device)
    // Row walk: initRowWalk sets the even and odd row positions (WorldView::rowEven/rowOdd) from the view's top-left
    // corner; cWorldView0_render then calls renderTileRow for each and steps it one tile row down (tile + 0x41,
    // y + 48), changing sector at sector edges. The camera position (view coordinates) is set by the same frame.
    inline uintptr_t cWorldView_initRowWalk{};          // DE 00632A30; thiscall (pos: +4 x, +8 y; map data)
    inline uintptr_t g_viewCameraX{};                   // DE 00AD5918; int32
    inline uintptr_t g_viewCameraY{};                   // DE 00AD591C; int32

    // Engine input: cEngine_receiveEvent (0x618130) passes mouse events to the UI manager first (UI coordinates)
    // and then to the world mouse handler, which picks with the event position.
    inline uintptr_t cEngine_worldMouse{};              // DE 00617360; thiscall (event, flag) -> bool
    inline uintptr_t cEventMouseDown_vtable{};          // DE 008950A8; x at +8, y at +0xC
    inline uintptr_t cEventMouseUp_vtable{};            // DE 00897248
    // World-side cursor reads, redirected to physical coordinates: calls to cMouse::getX (DE 006559E0),
    // cMouse::getY (006559F0) and cMouse_instance.
    inline uintptr_t worldGetXCalls[6]{};               // DE 00611FF4 0061203D 006127DC 00612868 00617E9C 00617F09
    inline uintptr_t worldGetYCalls[6]{};               // DE 00611FE7 00612030 006127ED 00612879 00617EAD 00617EFC
    inline uintptr_t worldMouseReads[5]{};              // DE 004FB6C1 0060F308 00610567 00611F63 0062772E

    // Record caches of the map data object (constructor 0x6336F0, clear 0x633F80): thiscall (id) -> record, 0 if
    // id is 0. Each looks the id up in its own std::map<uint32_t, record> (find 0x6404C0: thiscall (&key) on the
    // map, returns the node or the head as end; node +0x10 key, +0x14 record), stamps the node with the current
    // time (0xCD59D0) on a hit, and on a miss reads the record from a data file, inserts it and may evict the node
    // with the oldest stamp. 0x6360E0 holds the ground layer records (16 bytes, map at +0xDE5C, stamp node +0x24),
    // 0x635F50 the 64-byte records also used by game logic (map at +0xDE50, stamp node +0x54).
    inline uintptr_t layerRecordCache{};                // DE 006360E0
    inline uintptr_t recordCache{};                     // DE 00635F50
    inline uintptr_t recordMapFind{};                   // DE 006404C0
    inline uintptr_t g_recordStamp{};                   // DE 00CD59D0

    // Game client (cGCclass, one instance). cGCclass_initNetwork (0x7D2410) binds a UDP socket (SO_REUSEADDR) to
    // NETWORK_PORT_LISTEN for the LAN list; cGCclass_pollLanGames (0x7D2E20) reads the gameservers' announcements
    // from it with select/__WSAFDIsSet/recvfrom (their only use in the exe) and drops games that were silent for
    // 5 s. cGCclass_joinLanGame (0x7D3530) connects to the address inside the announcement.
    inline uintptr_t g_pGameClient{};                   // DE 0182CB70
    constexpr uintptr_t gameClient_lanSocket = 0x14;
    // cGCclass_initNetwork sets TinCat's drv_disable_nagle (TCP_NODELAY on the game connection) to
    // "data flow == LAN" (cGCclass + 0x40414 == 2): `cmp ebx, 2; sete al` after `xor eax, eax`.
    inline uintptr_t initNetworkNagleTest{};            // DE 007D294E

    // cWorldView0 vtable slot 5: draws the isometric world (arg: device).
    inline uintptr_t cWorldView0_render{};              // DE 006322B0

    // cUI_Manager::render(device): letterbox bars + all UI windows.
    inline uintptr_t cUI_Manager_render{};              // DE 007587B0
}

// dxDriver7 member offsets (identical in the ENG and DE builds).
namespace Sacred::DxDriver
{
    constexpr uintptr_t height = 0x1C;       // uint16
    constexpr uintptr_t width = 0x20;        // uint16
    constexpr uintptr_t windowed = 0x90;     // 1 = fullscreen, else windowed
    constexpr uintptr_t bpp = 0x94;
    constexpr uintptr_t hwnd = 0xB0;
    constexpr uintptr_t ddraw = 0xB4;        // IDirectDraw7*
    constexpr uintptr_t primary = 0xB8;      // IDirectDrawSurface7*
    constexpr uintptr_t back = 0xBC;         // IDirectDrawSurface7* (3D render target)
    constexpr uintptr_t d3d = 0xC8;          // IDirect3D7*
    constexpr uintptr_t device = 0xCC;       // IDirect3DDevice7*
}

// cUI_Control2 member offsets. Window children keep absolute screen coordinates.
namespace Sacred::UiControl
{
    constexpr uintptr_t flags = 0x10;        // bit 0: visible
    constexpr uintptr_t x = 0x24;
    constexpr uintptr_t y = 0x28;
    constexpr uintptr_t width = 0x2C;        // int16
    constexpr uintptr_t height = 0x2E;       // int16
    constexpr uintptr_t name = 0x30;         // char[0x20]
    constexpr uintptr_t parent = 0x50;
    constexpr uintptr_t childrenBegin = 0x78; // cUI_Window2 only: std::vector<cUI_Control2*>
    constexpr uintptr_t childrenEnd = 0x7C;
}

// cEngine member offsets.
namespace Sacred::Engine
{
    constexpr uintptr_t flags = 0x54;        // 0x10000 loading screen, 0x20000 fade out, 0x40000 fade in, 0x80000 black
}

// cWorldView member offsets (ground layers).
namespace Sacred::WorldView
{
    constexpr uintptr_t quadBatcher = 0x86890;
    constexpr uintptr_t layeredTileCount = 0x3FF1C;
    constexpr uint32_t layeredTileCapacity = 0x6D5;
    // Animated (water/lava, record type 0x90/0xA0) tiles: renderTileRow appends 0x98-byte entries at +0x3FF2C without
    // a bounds check; cWorldView_drawWaterTiles draws them after all rows. Entry 1750 would overwrite the count.
    constexpr uintptr_t waterTileCount = 0x80E3C;
    constexpr uint32_t waterTileCapacity = (0x80E3C - 0x3FF2C) / 0x98;
    // Row walk positions: x, y (float), tile (int16, row * 64 + column in its sector), sector (int16, 3x3 grid of
    // loaded sectors around the camera, row * 3 + column), steps (int16).
    constexpr uintptr_t rowEven = 0x970D4;
    constexpr uintptr_t rowOdd = 0x970E4;   // even + (48, 24): one tile column further
    constexpr uintptr_t rowEdgeLeft = 0x96AB8;  // 6: renderTileRow draws ground from column edgeLeft - 1 ...
    constexpr uintptr_t rowEdgeRight = 0x96ABC; // 6: ... to column rowLength - edgeRight + 1 (rest: margins)
    constexpr uintptr_t rowLength = 0x96AC8;    // tiles per row: view width / 96 + 12
}

// cTextureManager member offsets.
namespace Sacred::TextureManager
{
    constexpr uintptr_t usedBytes = 0xC001C;
    constexpr uintptr_t budgetBytes = 0xC0020;
}

// cMouse member offsets.
namespace Sacred::Mouse
{
    constexpr uintptr_t x = 0x04;
    constexpr uintptr_t y = 0x08;
}

// cUI_Manager: top-level game windows created by createGameWindows live in this pointer range.
namespace Sacred::UiManager
{
    constexpr uintptr_t flags = 0x08;        // 0x01 menus, 0x04 in game, 0x10 cinematic
    constexpr uintptr_t firstGameWindow = 0x80;
    constexpr uintptr_t lastGameWindow = 0xD8;
}
